318	    /* create source from buffer */
319	    zip_source* localZipSource = zip_source_buffer_create(*data, size, 0, &error);
320	    if (localZipSource == nullptr) {
321	        Helper::callErrorHandlingCallback(&error, "can't create zip source: %s\n", errorHandlingCallback);
322	        zip_error_fini(&error);
