        zip_unchange(zipHandle, *it);
    }
}

void ZipArchive::releaseOwnedBuffers(void) {
    for(vector<void*>::iterator it=ownedBuffers.begin() ; it!=ownedBuffers.end() ; ++it) {
        ::free(*it);
    }
    ownedBuffers.clear();
}

