// Regression tests for the atomic addFile/addData failure behavior.
#include <assert.h>
#include <string.h>
#include <cstdio>
#include <cstdlib>
#include <iostream>
#include "libzippp.h"
#include <zip.h>

using namespace std;
using namespace libzippp;

static void cleanup() {
    remove("rt.zip");
    remove("rt_source.txt");
}

// 1. addFile with a nonexistent source file: false, no entry, no parent dirs,
//    archive stays open and usable, nothing written to disk.
static void t_missing_source_file() {
    cout << "t_missing_source_file...";
    cleanup();
    ZipArchive z("rt.zip");
    assert(z.open(ZipArchive::Write));
    assert(z.addData("keep.txt", "K", 1)); //a pending change that must survive
    assert(!z.addFile("newdir/sub/missing.txt", "does_not_exist.txt"));
    assert(!z.hasEntry("newdir/sub/missing.txt"));
    assert(!z.hasEntry("newdir/"));
    assert(!z.hasEntry("newdir/sub/"));
    assert(z.isOpen());
    //the archive is still usable afterwards
    assert(z.addData("newdir2/ok.txt", "OK", 2));
    assert(z.close()==LIBZIPPP_OK);

    ZipArchive r("rt.zip");
    assert(r.open(ZipArchive::ReadOnly));
    assert(r.hasEntry("keep.txt"));
    assert(r.hasEntry("newdir2/"));
    assert(r.hasEntry("newdir2/ok.txt"));
    assert(!r.hasEntry("newdir/"));
    assert(r.close()==LIBZIPPP_OK);
    cleanup();
    cout << " ok" << endl;
}

// 2. addFile with an existing source file still works, parents created.
static void t_addfile_success() {
    cout << "t_addfile_success...";
    cleanup();
    FILE* f = fopen("rt_source.txt", "wb");
    fputs("file-content", f);
    fclose(f);
    ZipArchive z("rt.zip");
    assert(z.open(ZipArchive::New));
    assert(z.addFile("a/b/c.txt", "rt_source.txt"));
    assert(z.hasEntry("a/") && z.hasEntry("a/b/") && z.hasEntry("a/b/c.txt"));
    assert(z.close()==LIBZIPPP_OK);
    ZipArchive r("rt.zip");
    assert(r.open(ZipArchive::ReadOnly));
    ZipEntry e = r.getEntry("a/b/c.txt");
    assert(!e.isNull());
    assert(e.readAsText()=="file-content");
    assert(r.close()==LIBZIPPP_OK);
    cleanup();
    cout << " ok" << endl;
}

// 3. null data: length>0 rejected without side effects; length==0 allowed.
static void t_null_data() {
    cout << "t_null_data...";
    cleanup();
    ZipArchive z("rt.zip");
    assert(z.open(ZipArchive::New));
    assert(!z.addData("d/e/f.txt", nullptr, 10));
    assert(!z.hasEntry("d/"));
    assert(!z.hasEntry("d/e/f.txt"));
    assert(z.addData("d/e/empty.txt", nullptr, 0));
    assert(z.hasEntry("d/") && z.hasEntry("d/e/"));
    assert(z.close()==LIBZIPPP_OK);
    ZipArchive r("rt.zip");
    assert(r.open(ZipArchive::ReadOnly));
    ZipEntry e = r.getEntry("d/e/empty.txt");
    assert(!e.isNull());
    assert(e.getSize()==0);
    assert(r.close()==LIBZIPPP_OK);
    cleanup();
    cout << " ok" << endl;
}

// 4. unsupported compression: false, no silent fallback, no entry/dirs, state preserved.
static void t_unsupported_compression() {
    cout << "t_unsupported_compression...";
    cleanup();
    ZipArchive z("rt.zip");
    assert(z.open(ZipArchive::New));
    z.setCompressionMethod(CompressionMethod::DEFLATE);
    assert(z.addData("dir/file.txt", "v1-content", 10));
    ZipEntry e = z.getEntry("dir/file.txt");
    assert(!e.isNull());
    assert(e.setComment("my-comment"));
    assert(z.setComment("archive-comment"));
    assert(z.addData("other.txt", "O", 1));

    //an out-of-range compression method maps to an unsupported libzip method
    z.setCompressionMethod((CompressionMethod)999);
    assert(!z.addData("dir/file.txt", "v2-content", 10)); //overwrite fails
    assert(!z.addData("brand/new.txt", "x", 1));          //new entry fails

    //the pre-call state is fully preserved
    assert(z.isOpen());
    assert(!z.hasEntry("brand/"));
    assert(!z.hasEntry("brand/new.txt"));
    assert(z.hasEntry("dir/"));
    assert(z.hasEntry("other.txt"));
    ZipEntry e2 = z.getEntry("dir/file.txt");
    assert(!e2.isNull());
    assert(e2.readAsText()=="v1-content");          //previous content still readable
    assert(z.getEntryComment(e2)=="my-comment");    //comment preserved
    assert(z.getComment()=="archive-comment");      //archive comment preserved
    assert(e.readAsText()=="v1-content");           //previously obtained entry still usable

    //the caller can switch back to supported settings and commit with the same close()
    z.setCompressionMethod(CompressionMethod::DEFLATE);
    assert(z.addData("dir/file.txt", "v2-content", 10));
    assert(z.close()==LIBZIPPP_OK);

    ZipArchive r("rt.zip");
    assert(r.open(ZipArchive::ReadOnly));
    ZipEntry re = r.getEntry("dir/file.txt");
    assert(!re.isNull());
    assert(re.readAsText()=="v2-content");
    assert(re.getCompressionMethod()==CompressionMethod::DEFLATE);
    assert(r.getEntryComment(re)=="my-comment");
    assert(r.getComment()=="archive-comment");
    assert(r.hasEntry("other.txt"));
    assert(!r.hasEntry("brand/"));
    assert(r.close()==LIBZIPPP_OK);
    cleanup();
    cout << " ok" << endl;
}

// 5. encrypted archive: success path applies encryption; readable with password.
static void t_encryption_applied() {
    cout << "t_encryption_applied...";
    cleanup();
    {
        ZipArchive z("rt.zip", "passw0rd", ZipArchive::Encryption::Aes256);
        assert(z.open(ZipArchive::New));
        assert(z.addData("secret/data.txt", "s3cret", 6));
        assert(z.close()==LIBZIPPP_OK);
    }
    {
        ZipArchive r("rt.zip", "passw0rd", ZipArchive::Encryption::Aes256);
        assert(r.open(ZipArchive::ReadOnly));
        ZipEntry e = r.getEntry("secret/data.txt");
        assert(!e.isNull());
        assert(e.getEncryptionMethod()==ZIP_EM_AES_256);
        assert(e.readAsText()=="s3cret");
        assert(r.close()==LIBZIPPP_OK);
    }
    cleanup();
    cout << " ok" << endl;
}

// 6. freeData=true on a failing call: caller keeps ownership and frees immediately;
//    archive remains usable and close() does not crash.
static void t_freedata_failure_caller_frees() {
    cout << "t_freedata_failure_caller_frees...";
    cleanup();
    ZipArchive z("rt.zip");
    assert(z.open(ZipArchive::New));
    z.setCompressionMethod((CompressionMethod)999); //unsupported -> addData will fail
    char* buf = (char*)malloc(6);
    memcpy(buf, "hello", 6);
    assert(!z.addData("x/y.txt", buf, 5, true));
    free(buf); //caller still owns it: freed immediately, must not be freed again later
    z.setCompressionMethod(CompressionMethod::DEFLATE);
    assert(z.addData("x/y.txt", "world", 5));
    assert(z.close()==LIBZIPPP_OK);
    cleanup();
    cout << " ok" << endl;
}

// 7. freeData=true success + repeated overwrite + commit: freed exactly once (checked
//    under valgrind/ASAN; here we check functional correctness and absence of crashes).
static void t_freedata_success_and_overwrite() {
    cout << "t_freedata_success_and_overwrite...";
    cleanup();
    ZipArchive z("rt.zip");
    assert(z.open(ZipArchive::New));
    for (int i=0 ; i<3 ; ++i) {
        char* buf = (char*)malloc(8);
        snprintf(buf, 8, "content%d", i);
        assert(z.addData("f.txt", buf, 8, true));
    }
    assert(z.close()==LIBZIPPP_OK);
    ZipArchive r("rt.zip");
    assert(r.open(ZipArchive::ReadOnly));
    assert(r.getEntry("f.txt").readAsText().substr(0,7)=="content");
    assert(r.close()==LIBZIPPP_OK);
    cleanup();
