    z.setCompressionMethod((CompressionMethod)999);
    assert(!z.addFile("p/q/r.txt", "rt_source.txt"));
    assert(!z.hasEntry("p/"));
    assert(!z.hasEntry("p/q/"));
    assert(!z.hasEntry("p/q/r.txt"));
    z.setCompressionMethod(CompressionMethod::STORE);
    assert(z.addFile("p/q/r.txt", "rt_source.txt")); //retry with supported settings
    assert(z.close()==LIBZIPPP_OK);
    ZipArchive r("rt.zip");
    assert(r.open(ZipArchive::ReadOnly));
    ZipEntry e = r.getEntry("p/q/r.txt");
    assert(!e.isNull());
    assert(e.getCompressionMethod()==CompressionMethod::STORE);
    assert(r.close()==LIBZIPPP_OK);
    cleanup();
    cout << " ok" << endl;
}

// 13. on an encrypted archive, a failed overwrite preserves the pending entry
//     including its encryption; the commit then produces an encrypted entry.
static void t_encrypted_archive_failed_overwrite() {
    cout << "t_encrypted_archive_failed_overwrite...";
    cleanup();
    ZipArchive z("rt.zip", "pw", ZipArchive::Encryption::Aes256);
    assert(z.open(ZipArchive::New));
    assert(z.addData("s.txt", "enc-v1", 6));
    ZipEntry e = z.getEntry("s.txt");
    assert(e.setComment("note"));
    z.setCompressionMethod((CompressionMethod)999); //unsupported -> failure
    assert(!z.addData("s.txt", "enc-v2", 6));
    assert(z.getEntryComment(z.getEntry("s.txt"))=="note");
    z.setCompressionMethod(CompressionMethod::DEFAULT);
    assert(z.addData("s.txt", "enc-v2", 6)); //retry works
    assert(z.close()==LIBZIPPP_OK);
    ZipArchive r("rt.zip", "pw", ZipArchive::Encryption::Aes256);
    assert(r.open(ZipArchive::ReadOnly));
    ZipEntry re = r.getEntry("s.txt");
    assert(!re.isNull());
    assert(re.getEncryptionMethod()==ZIP_EM_AES_256);
    assert(re.readAsText()=="enc-v2");
    assert(r.getEntryComment(re)=="note");
    assert(r.close()==LIBZIPPP_OK);
    cleanup();
    cout << " ok" << endl;
}
'''
